{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile against a plain light background. Its entire body except for the back is covered in dense, shaggy brown fur with lighter tan on the muzzle, chest and belly. The back and shoulders are covered by a large, glossy, dark brown domed shell that looks hard and smooth with reflective highlights. The head is broad and bear-like with a single curved black horn on the nose, and the feet are large clawed paws. The overall form combines a furry mammal body with a hard beetle-like carapace on top.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head with short muzzle, dark eyes, and dense brown fur, lighter tan fur around the nose and mouth",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single thick black horn, curved upward and pointed at the tip, with a smooth surface",
      "where": "on the top of the nose/muzzle at the front of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears with dark brown fur",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "mane",
      "looks_like": "no distinct mane; thick shaggy brown fur around the neck and shoulders that is part of the overall coat",
      "where": "around the neck and shoulder area behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy legs covered in long shaggy dark brown fur",
      "where": "two front legs under the shoulder and two hind legs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large paws with visible long curved claws on each toe, the soles are lighter brown",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short tuft of brown fur, barely protruding",
      "where": "at the rear left end of the body, partially tucked under the lower edge of the shell"
    },
    {
      "part": "wings",
      "looks_like": "none visible",
      "where": "not present"
    },
    {
      "part": "gills",
      "looks_like": "none visible",
      "where": "not present"
    },
    {
      "part": "tentacles",
      "looks_like": "none visible",
      "where": "not present"
    },
    {
      "part": "shell",
      "looks_like": "large glossy dark brown domed carapace with a smooth reflective surface and fine horizontal ridges on the rear dome, divided into a smaller shoulder plate and a larger rear dome",
      "where": "covering the entire back from behind the neck to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "a row of small rectangular brown plates forming a segmented fringe along the lower edge of the shell, and a visible seam between the two main shell sections",
      "where": "along the bottom margin of the shell encircling the lower edge, and between the shoulder and back sections"
    },
    {
      "part": "scales",
      "looks_like": "none visible; the back is covered by the hard shell rather than scales",
      "where": "not present"
    },
    {
      "part": "feathers",
      "looks_like": "none visible",
      "where": "not present"
    },
    {
      "part": "markings",
      "looks_like": "lighter cream-tan fur on the muzzle, lower cheek, chest, and belly contrasting with the darker brown fur elsewhere",
      "where": "on the front of the face around the nose and mouth, on the chest between the front legs, and on the underside of the belly"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
